export const ADMIN_CSS = "/**\n * RAKHI MAKEOVERS - LUXURY ADMIN DASHBOARD STYLESHEET\n */\n\n:root {\n  --bg-dark-base: #0B0409;\n  --bg-dark-surface: #140811;\n  --bg-dark-card: rgba(26, 12, 22, 0.75);\n  --bg-glass: rgba(30, 15, 26, 0.65);\n  --border-glass: rgba(212, 175, 55, 0.2);\n  --border-glass-hover: rgba(212, 175, 55, 0.45);\n\n  --color-gold-primary: #D4AF37;\n  --color-gold-light: #F4E0A5;\n  --color-gold-dark: #A68020;\n  --color-rose-gold: #C59B76;\n  --color-accent-pink: #E85D75;\n\n  --color-text-main: #FDFBF7;\n  --color-text-muted: #B8A8B4;\n  --color-text-dim: #7E6F7A;\n\n  --color-danger: #EF4444;\n  --color-success: #10B981;\n  --color-warning: #F59E0B;\n\n  --font-serif: 'Cormorant Garamond', Georgia, serif;\n  --font-sans: 'Montserrat', -apple-system, BlinkMacSystemFont, sans-serif;\n\n  --radius-sm: 8px;\n  --radius-md: 12px;\n  --radius-lg: 16px;\n  --radius-full: 9999px;\n\n  --shadow-luxury: 0 10px 30px -5px rgba(0, 0, 0, 0.6), 0 0 20px rgba(212, 175, 55, 0.1);\n  --shadow-glow: 0 0 15px rgba(212, 175, 55, 0.25);\n  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody.admin-body {\n  font-family: var(--font-sans);\n  background: var(--bg-dark-base);\n  color: var(--color-text-main);\n  min-height: 100vh;\n  line-height: 1.5;\n  background-image: \n    radial-gradient(circle at 10% 20%, rgba(212, 175, 55, 0.05) 0%, transparent 40%),\n    radial-gradient(circle at 90% 80%, rgba(197, 155, 118, 0.06) 0%, transparent 45%);\n  background-attachment: fixed;\n  overflow-x: hidden;\n}\n\n/* Glass Panels */\n.glass-panel {\n  background: var(--bg-glass);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border: 1px solid var(--border-glass);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-luxury);\n}\n\n/* Typography Utilities */\n.gold-text { color: var(--color-gold-primary); }\n.text-gold { color: var(--color-gold-primary); }\n.text-danger { color: var(--color-danger); }\n\n/* ==========================================================================\n   LOGIN SCREEN\n   ========================================================================== */\n.login-wrapper {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 100vh;\n  padding: 1.5rem;\n}\n\n.login-card {\n  width: 100%;\n  max-width: 440px;\n  padding: 2.5rem 2.25rem;\n  text-align: center;\n}\n\n.login-brand {\n  margin-bottom: 1.25rem;\n}\n\n.brand-logo-main {\n  font-family: var(--font-serif);\n  font-size: 1.85rem;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  color: #FFFFFF;\n}\n\n.brand-logo-main span {\n  color: var(--color-gold-primary);\n  font-style: italic;\n  font-weight: 500;\n}\n\n.brand-logo-sub {\n  font-size: 0.725rem;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  color: var(--color-rose-gold);\n  margin-top: 0.15rem;\n}\n\n.login-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  background: rgba(212, 175, 55, 0.12);\n  border: 1px solid rgba(212, 175, 55, 0.3);\n  color: var(--color-gold-light);\n  padding: 0.35rem 0.85rem;\n  border-radius: var(--radius-full);\n  font-size: 0.75rem;\n  font-weight: 600;\n  margin-bottom: 1.75rem;\n}\n\n.login-form {\n  text-align: left;\n}\n\n.login-footer-hint {\n  text-align: center;\n  margin-top: 1.5rem;\n  font-size: 0.72rem;\n  color: var(--color-text-dim);\n}\n\n/* ==========================================================================\n   FORM CONTROLS\n   ========================================================================== */\n.form-group {\n  margin-bottom: 1.25rem;\n}\n\n.form-label {\n  display: block;\n  font-size: 0.785rem;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--color-text-muted);\n  margin-bottom: 0.45rem;\n}\n\n.input-icon-wrap {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n\n.input-icon {\n  position: absolute;\n  left: 1rem;\n  color: var(--color-gold-primary);\n  font-size: 0.9rem;\n  pointer-events: none;\n}\n\n.form-input, .form-select, .form-textarea {\n  width: 100%;\n  background: rgba(15, 6, 13, 0.8);\n  border: 1px solid rgba(212, 175, 55, 0.25);\n  border-radius: var(--radius-md);\n  padding: 0.75rem 1rem;\n  color: var(--color-text-main);\n  font-family: inherit;\n  font-size: 0.875rem;\n  outline: none;\n  transition: var(--transition);\n}\n\n.input-icon-wrap .form-input {\n  padding-left: 2.75rem;\n}\n\n.form-input:focus, .form-select:focus, .form-textarea:focus {\n  border-color: var(--color-gold-primary);\n  box-shadow: 0 0 12px rgba(212, 175, 55, 0.25);\n  background: rgba(22, 10, 19, 0.95);\n}\n\n.form-select option {\n  background: #1A0C16;\n  color: #FFFFFF;\n}\n\n.btn-toggle-pw {\n  position: absolute;\n  right: 1rem;\n  background: none;\n  border: none;\n  color: var(--color-text-muted);\n  cursor: pointer;\n  font-size: 0.9rem;\n}\n\n.btn-toggle-pw:hover {\n  color: var(--color-gold-light);\n}\n\n.form-grid-2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1rem;\n}\n\n@media (max-width: 600px) {\n  .form-grid-2 {\n    grid-template-columns: 1fr;\n  }\n}\n\n/* ==========================================================================\n   BUTTONS\n   ========================================================================== */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1.4rem;\n  border-radius: var(--radius-md);\n  font-family: inherit;\n  font-size: 0.85rem;\n  font-weight: 600;\n  letter-spacing: 0.03em;\n  cursor: pointer;\n  border: none;\n  transition: var(--transition);\n  text-decoration: none;\n}\n\n.btn-gold {\n  background: linear-gradient(135deg, #E5C365 0%, #D4AF37 50%, #B89020 100%);\n  color: #0F050C;\n  box-shadow: 0 4px 15px rgba(212, 175, 55, 0.3);\n}\n\n.btn-gold:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.45);\n}\n\n.btn-outline-gold {\n  background: transparent;\n  border: 1px solid var(--color-gold-primary);\n  color: var(--color-gold-light);\n}\n\n.btn-outline-gold:hover {\n  background: rgba(212, 175, 55, 0.15);\n  border-color: var(--color-gold-light);\n}\n\n.btn-secondary {\n  background: rgba(255, 255, 255, 0.08);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  color: var(--color-text-main);\n}\n\n.btn-secondary:hover {\n  background: rgba(255, 255, 255, 0.15);\n}\n\n.btn-danger {\n  background: #DC2626;\n  color: #FFFFFF;\n}\n\n.btn-danger:hover {\n  background: #B91C1C;\n}\n\n.btn-danger-ghost {\n  background: rgba(239, 68, 68, 0.1);\n  color: #F87171;\n  border: 1px solid rgba(239, 68, 68, 0.25);\n}\n\n.btn-danger-ghost:hover {\n  background: rgba(239, 68, 68, 0.25);\n  color: #FFFFFF;\n}\n\n.btn-block {\n  width: 100%;\n}\n\n.btn-sm {\n  padding: 0.45rem 0.85rem;\n  font-size: 0.775rem;\n}\n\n.btn-icon {\n  background: transparent;\n  border: none;\n  color: var(--color-text-muted);\n  font-size: 1.15rem;\n  cursor: pointer;\n  padding: 0.4rem;\n}\n\n.btn-icon:hover {\n  color: var(--color-gold-primary);\n}\n\n/* ==========================================================================\n   APP LAYOUT (HEADER + SIDEBAR + CONTENT)\n   ========================================================================== */\n.admin-app-layout {\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n\n.admin-header {\n  height: 70px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 1.5rem;\n  border-radius: 0;\n  border-top: none;\n  border-left: none;\n  border-right: none;\n  border-bottom: 1px solid var(--border-glass);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.header-left, .header-right {\n  display: flex;\n  align-items: center;\n  gap: 1.25rem;\n}\n\n.admin-brand .brand-title {\n  font-family: var(--font-serif);\n  font-size: 1.35rem;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n}\n\n.admin-brand .brand-tag {\n  font-size: 0.65rem;\n  background: rgba(212, 175, 55, 0.15);\n  border: 1px solid rgba(212, 175, 55, 0.3);\n  color: var(--color-gold-light);\n  padding: 0.15rem 0.45rem;\n  border-radius: var(--radius-sm);\n  margin-left: 0.5rem;\n  text-transform: uppercase;\n  font-weight: 600;\n}\n\n.live-status-pill {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.75rem;\n  color: var(--color-text-muted);\n  background: rgba(16, 185, 129, 0.1);\n  padding: 0.35rem 0.75rem;\n  border-radius: var(--radius-full);\n  border: 1px solid rgba(16, 185, 129, 0.25);\n}\n\n.status-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--color-success);\n  box-shadow: 0 0 8px var(--color-success);\n}\n\n.admin-user-menu {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  padding-left: 0.75rem;\n  border-left: 1px solid rgba(255, 255, 255, 0.1);\n}\n\n.user-avatar {\n  width: 32px;\n  height: 32px;\n  border-radius: 50%;\n  background: rgba(212, 175, 55, 0.2);\n  color: var(--color-gold-light);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.85rem;\n}\n\n.user-name {\n  font-size: 0.825rem;\n  font-weight: 600;\n}\n\n.admin-workspace {\n  display: flex;\n  flex: 1;\n}\n\n/* Sidebar */\n.admin-sidebar {\n  width: 250px;\n  border-radius: 0;\n  border-top: none;\n  border-left: none;\n  border-bottom: none;\n  border-right: 1px solid var(--border-glass);\n  padding: 1.5rem 1rem;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n\n.sidebar-nav {\n  display: flex;\n  flex-direction: column;\n  gap: 0.4rem;\n}\n\n.nav-item {\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n  width: 100%;\n  padding: 0.8rem 1rem;\n  background: transparent;\n  border: 1px solid transparent;\n  border-radius: var(--radius-md);\n  color: var(--color-text-muted);\n  font-family: inherit;\n  font-size: 0.85rem;\n  font-weight: 600;\n  cursor: pointer;\n  text-align: left;\n  transition: var(--transition);\n}\n\n.nav-item i {\n  font-size: 1rem;\n  width: 20px;\n  color: var(--color-text-dim);\n  transition: var(--transition);\n}\n\n.nav-item:hover {\n  background: rgba(255, 255, 255, 0.05);\n  color: var(--color-text-main);\n}\n\n.nav-item:hover i {\n  color: var(--color-gold-light);\n}\n\n.nav-item.active {\n  background: rgba(212, 175, 55, 0.12);\n  border-color: rgba(212, 175, 55, 0.35);\n  color: var(--color-gold-light);\n}\n\n.nav-item.active i {\n  color: var(--color-gold-primary);\n}\n\n.sidebar-footer {\n  margin-top: 2rem;\n}\n\n.cf-hosting-badge {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  padding: 0.75rem;\n  background: rgba(0, 0, 0, 0.3);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-md);\n  font-size: 0.75rem;\n}\n\n.cf-hosting-badge i {\n  font-size: 1.25rem;\n  color: #F6821F; /* Cloudflare Orange */\n}\n\n.cf-hosting-badge strong {\n  display: block;\n  color: #FFFFFF;\n}\n\n.cf-hosting-badge small {\n  color: var(--color-text-dim);\n}\n\n/* Main Content */\n.admin-content {\n  flex: 1;\n  padding: 2rem 2.5rem;\n  overflow-y: auto;\n}\n\n.tab-pane {\n  display: none;\n}\n\n.tab-pane.active {\n  display: block;\n  animation: fadeIn 0.25s ease-in-out;\n}\n\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(6px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n.page-title-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 2rem;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n\n.page-title {\n  font-family: var(--font-serif);\n  font-size: 1.85rem;\n  font-weight: 700;\n  color: #FFFFFF;\n}\n\n.page-subtitle {\n  font-size: 0.85rem;\n  color: var(--color-text-muted);\n  margin-top: 0.2rem;\n}\n\n/* ==========================================================================\n   STATS CARDS GRID\n   ========================================================================== */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 1.25rem;\n  margin-bottom: 2rem;\n}\n\n.stat-card {\n  padding: 1.5rem;\n  display: flex;\n  align-items: center;\n  gap: 1.25rem;\n}\n\n.stat-icon {\n  width: 52px;\n  height: 52px;\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.35rem;\n}\n\n.stat-icon.gold { background: rgba(212, 175, 55, 0.15); color: var(--color-gold-primary); }\n.stat-icon.rose { background: rgba(197, 155, 118, 0.15); color: var(--color-rose-gold); }\n.stat-icon.amber { background: rgba(245, 158, 11, 0.15); color: #F59E0B; }\n.stat-icon.emerald { background: rgba(16, 185, 129, 0.15); color: #10B981; }\n\n.stat-number {\n  display: block;\n  font-family: var(--font-serif);\n  font-size: 1.75rem;\n  font-weight: 700;\n  line-height: 1.1;\n  color: #FFFFFF;\n}\n\n.stat-label {\n  font-size: 0.775rem;\n  color: var(--color-text-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.dashboard-sections-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1.5rem;\n}\n\n@media (max-width: 900px) {\n  .dashboard-sections-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.dashboard-card {\n  padding: 1.75rem;\n}\n\n.card-heading {\n  font-family: var(--font-serif);\n  font-size: 1.25rem;\n  font-weight: 700;\n  margin-bottom: 1.25rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.quick-action-btns {\n  display: flex;\n  flex-direction: column;\n  gap: 0.75rem;\n}\n\n.info-checklist {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 0.85rem;\n  font-size: 0.85rem;\n}\n\n.info-checklist li {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.65rem;\n  color: var(--color-text-muted);\n  line-height: 1.4;\n}\n\n.info-checklist li i {\n  margin-top: 0.2rem;\n}\n\n/* ==========================================================================\n   CRUD CARDS GRID (SERVICES, GALLERY, REVIEWS)\n   ========================================================================== */\n.admin-cards-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n  gap: 1.5rem;\n}\n\n.admin-item-card {\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  transition: var(--transition);\n}\n\n.admin-item-card:hover {\n  transform: translateY(-4px);\n  border-color: var(--border-glass-hover);\n}\n\n.item-card-media {\n  position: relative;\n  height: 180px;\n  overflow: hidden;\n  background: #000;\n}\n\n.item-card-media img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.item-badge-pill {\n  position: absolute;\n  top: 0.75rem;\n  left: 0.75rem;\n  background: rgba(11, 4, 9, 0.85);\n  backdrop-filter: blur(8px);\n  color: var(--color-gold-light);\n  font-size: 0.72rem;\n  font-weight: 600;\n  padding: 0.25rem 0.65rem;\n  border-radius: var(--radius-full);\n  border: 1px solid rgba(212, 175, 55, 0.3);\n}\n\n.item-duration-pill {\n  position: absolute;\n  bottom: 0.75rem;\n  right: 0.75rem;\n  background: rgba(0, 0, 0, 0.75);\n  color: var(--color-text-muted);\n  font-size: 0.72rem;\n  padding: 0.2rem 0.55rem;\n  border-radius: var(--radius-full);\n}\n\n.item-card-body {\n  padding: 1.25rem;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n}\n\n.item-card-title {\n  font-family: var(--font-serif);\n  font-size: 1.2rem;\n  font-weight: 700;\n  color: #FFFFFF;\n  margin-bottom: 0.4rem;\n}\n\n.item-card-desc {\n  font-size: 0.825rem;\n  color: var(--color-text-muted);\n  line-height: 1.45;\n  margin-bottom: 0.85rem;\n  flex: 1;\n}\n\n.item-inclusions-preview {\n  list-style: none;\n  font-size: 0.775rem;\n  color: var(--color-text-dim);\n  margin-bottom: 1rem;\n}\n\n.item-inclusions-preview li {\n  margin-bottom: 0.2rem;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.item-card-actions {\n  display: flex;\n  gap: 0.6rem;\n  padding-top: 0.85rem;\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* Gallery Grid */\n.admin-gallery-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));\n  gap: 1.25rem;\n}\n\n.admin-gallery-card {\n  position: relative;\n  border-radius: var(--radius-lg);\n  overflow: hidden;\n  height: 320px;\n  box-shadow: var(--shadow-luxury);\n  border: 1px solid var(--border-glass);\n}\n\n.admin-gallery-card img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  transition: transform 0.4s ease;\n}\n\n.admin-gallery-card:hover img {\n  transform: scale(1.05);\n}\n\n.gallery-card-overlay {\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(to top, rgba(11, 4, 9, 0.95) 0%, rgba(11, 4, 9, 0.2) 60%, transparent 100%);\n  display: flex;\n  flex-direction: column;\n  justify-content: flex-end;\n  padding: 1rem;\n}\n\n.gallery-card-title {\n  font-family: var(--font-serif);\n  font-size: 1.15rem;\n  font-weight: 700;\n  color: #FFFFFF;\n}\n\n.gallery-card-cat {\n  font-size: 0.72rem;\n  color: var(--color-gold-light);\n  text-transform: uppercase;\n  font-weight: 600;\n  margin-bottom: 0.25rem;\n}\n\n.gallery-card-actions {\n  display: flex;\n  gap: 0.5rem;\n  margin-top: 0.75rem;\n}\n\n/* Reviews Grid */\n.admin-reviews-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n  gap: 1.25rem;\n}\n\n.admin-review-card {\n  padding: 1.4rem;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n\n.review-card-top {\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n  margin-bottom: 0.85rem;\n}\n\n.review-avatar-img {\n  width: 44px;\n  height: 44px;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 1px solid var(--color-gold-primary);\n}\n\n.review-author-name {\n  font-weight: 700;\n  font-size: 0.95rem;\n  color: #FFFFFF;\n}\n\n.review-meta {\n  font-size: 0.725rem;\n  color: var(--color-text-dim);\n}\n\n.review-stars {\n  color: #F59E0B;\n  font-size: 0.85rem;\n  margin-bottom: 0.65rem;\n}\n\n.review-quote-text {\n  font-size: 0.835rem;\n  color: var(--color-text-muted);\n  line-height: 1.5;\n  font-style: italic;\n  flex: 1;\n  margin-bottom: 1rem;\n}\n\n/* Settings Grid */\n.settings-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1.5rem;\n}\n\n@media (max-width: 900px) {\n  .settings-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.settings-card {\n  padding: 1.75rem;\n}\n\n.studio-info-list {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.info-item {\n  display: flex;\n  justify-content: space-between;\n  padding-bottom: 0.75rem;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n  font-size: 0.85rem;\n}\n\n.info-label {\n  color: var(--color-text-dim);\n}\n\n.info-val {\n  font-weight: 600;\n  color: #FFFFFF;\n}\n\n/* ==========================================================================\n   DROPZONE / FILE UPLOAD\n   ========================================================================== */\n.dropzone {\n  border: 2px dashed rgba(212, 175, 55, 0.3);\n  border-radius: var(--radius-md);\n  padding: 1.5rem;\n  text-align: center;\n  background: rgba(11, 4, 9, 0.5);\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.dropzone:hover {\n  border-color: var(--color-gold-primary);\n  background: rgba(212, 175, 55, 0.05);\n}\n\n.dropzone-icon {\n  font-size: 2rem;\n  color: var(--color-gold-primary);\n  margin-bottom: 0.5rem;\n  display: block;\n}\n\n.dropzone-content span {\n  display: block;\n  font-size: 0.85rem;\n  font-weight: 600;\n  color: var(--color-text-main);\n}\n\n.dropzone-content small {\n  display: block;\n  font-size: 0.72rem;\n  color: var(--color-text-dim);\n  margin-top: 0.2rem;\n}\n\n.dropzone-preview {\n  position: relative;\n  max-width: 200px;\n  margin: 0 auto;\n  border-radius: var(--radius-sm);\n  overflow: hidden;\n}\n\n.dropzone-preview img {\n  width: 100%;\n  height: 120px;\n  object-fit: cover;\n  border-radius: var(--radius-sm);\n}\n\n.btn-remove-preview {\n  position: absolute;\n  top: 0.35rem;\n  right: 0.35rem;\n  background: rgba(220, 38, 38, 0.85);\n  color: #FFFFFF;\n  border: none;\n  border-radius: 50%;\n  width: 26px;\n  height: 26px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.75rem;\n}\n\n/* ==========================================================================\n   MODALS\n   ========================================================================== */\n.admin-modal {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n  display: none;\n  align-items: center;\n  justify-content: center;\n  padding: 1.5rem;\n}\n\n.admin-modal.active {\n  display: flex;\n  animation: fadeIn 0.2s ease-out;\n}\n\n.modal-backdrop {\n  position: absolute;\n  inset: 0;\n  background: rgba(5, 2, 4, 0.85);\n  backdrop-filter: blur(8px);\n}\n\n.modal-content {\n  position: relative;\n  width: 100%;\n  max-width: 650px;\n  max-height: 90vh;\n  overflow-y: auto;\n  z-index: 10;\n  padding: 1.75rem 2rem;\n}\n\n.modal-content.modal-sm {\n  max-width: 420px;\n}\n\n.modal-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 1.5rem;\n  padding-bottom: 0.85rem;\n  border-bottom: 1px solid var(--border-glass);\n}\n\n.modal-title {\n  font-family: var(--font-serif);\n  font-size: 1.4rem;\n  font-weight: 700;\n  color: #FFFFFF;\n}\n\n.modal-close-btn {\n  background: none;\n  border: none;\n  color: var(--color-text-muted);\n  font-size: 1.25rem;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.modal-close-btn:hover {\n  color: var(--color-gold-primary);\n}\n\n.modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 0.75rem;\n  margin-top: 1.5rem;\n  padding-top: 1rem;\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* ==========================================================================\n   TOAST NOTIFICATIONS\n   ========================================================================== */\n.toast-container {\n  position: fixed;\n  top: 1.5rem;\n  right: 1.5rem;\n  z-index: 2000;\n  display: flex;\n  flex-direction: column;\n  gap: 0.75rem;\n}\n\n.toast {\n  min-width: 280px;\n  max-width: 380px;\n  padding: 0.85rem 1.25rem;\n  background: rgba(22, 10, 19, 0.95);\n  backdrop-filter: blur(12px);\n  border: 1px solid var(--border-glass);\n  border-radius: var(--radius-md);\n  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  font-size: 0.825rem;\n  animation: slideInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  transition: opacity 0.3s ease, transform 0.3s ease;\n}\n\n.toast.toast-success { border-color: var(--color-success); }\n.toast.toast-success i { color: var(--color-success); }\n.toast.toast-error { border-color: var(--color-danger); }\n.toast.toast-error i { color: var(--color-danger); }\n\n@keyframes slideInRight {\n  from { opacity: 0; transform: translateX(40px); }\n  to { opacity: 1; transform: translateX(0); }\n}\n\n/* Alert Banner */\n.alert-banner {\n  padding: 0.75rem 1rem;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  margin-bottom: 1.25rem;\n}\n\n.alert-error {\n  background: rgba(239, 68, 68, 0.15);\n  border: 1px solid rgba(239, 68, 68, 0.3);\n  color: #FCA5A5;\n}\n\n.alert-success {\n  background: rgba(16, 185, 129, 0.15);\n  border: 1px solid rgba(16, 185, 129, 0.3);\n  color: #6EE7B7;\n}\n\n.loading-spinner {\n  text-align: center;\n  padding: 3rem;\n  color: var(--color-gold-light);\n  font-size: 1rem;\n  grid-column: 1 / -1;\n}\n\n/* ==========================================================================\n   MOBILE ADMIN NAVIGATION TABS STRIP & RESPONSIVE RULES\n   ========================================================================== */\n.mobile-admin-tabs {\n  display: none;\n}\n\n@media (max-width: 768px) {\n  .admin-header {\n    height: 60px;\n    padding: 0 1rem;\n  }\n\n  .admin-brand .brand-title {\n    font-size: 1.15rem;\n  }\n\n  .live-status-pill {\n    display: none;\n  }\n\n  .user-name {\n    display: none;\n  }\n\n  /* Sticky Horizontal Nav Strip for Phone View */\n  .mobile-admin-tabs {\n    display: flex;\n    align-items: center;\n    gap: 0.45rem;\n    padding: 0.5rem 0.85rem;\n    background: rgba(14, 6, 12, 0.96);\n    backdrop-filter: blur(16px);\n    -webkit-backdrop-filter: blur(16px);\n    border-bottom: 1px solid var(--border-glass);\n    position: sticky;\n    top: 60px;\n    z-index: 95;\n    overflow-x: auto;\n    -webkit-overflow-scrolling: touch;\n    scrollbar-width: none;\n  }\n\n  .mobile-admin-tabs::-webkit-scrollbar {\n    display: none;\n  }\n\n  .mobile-tab-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.45rem;\n    padding: 0.45rem 0.85rem;\n    border-radius: var(--radius-full);\n    background: rgba(255, 255, 255, 0.04);\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    color: var(--color-text-muted);\n    font-size: 0.75rem;\n    font-weight: 600;\n    white-space: nowrap;\n    cursor: pointer;\n    transition: var(--transition);\n    flex-shrink: 0;\n  }\n\n  .mobile-tab-btn i {\n    font-size: 0.8rem;\n    color: var(--color-text-dim);\n  }\n\n  .mobile-tab-btn.active {\n    background: rgba(212, 175, 55, 0.18);\n    border-color: rgba(212, 175, 55, 0.5);\n    color: var(--color-gold-light);\n  }\n\n  .mobile-tab-btn.active i {\n    color: var(--color-gold-primary);\n  }\n\n  .admin-sidebar {\n    display: none; /* Replaced by top touch ribbon on phones */\n  }\n\n  .admin-content {\n    padding: 1rem 0.85rem 3.5rem;\n  }\n\n  .page-title {\n    font-size: 1.35rem;\n  }\n\n  .page-subtitle {\n    font-size: 0.78rem;\n    margin-top: 0.15rem;\n  }\n\n  .page-title-row {\n    margin-bottom: 1.25rem;\n    gap: 0.75rem;\n  }\n\n  .page-title-row .page-actions {\n    width: 100%;\n  }\n\n  .page-title-row .page-actions .btn {\n    width: 100%;\n    justify-content: center;\n  }\n\n  /* 2x2 Clean Mobile Metric Stats Grid */\n  .stats-grid {\n    grid-template-columns: repeat(2, 1fr);\n    gap: 0.75rem;\n    margin-bottom: 1.25rem;\n  }\n\n  .stat-card {\n    padding: 0.85rem;\n    gap: 0.65rem;\n  }\n\n  .stat-icon {\n    width: 38px;\n    height: 38px;\n    font-size: 1.05rem;\n    border-radius: var(--radius-sm);\n  }\n\n  .stat-number {\n    font-size: 1.35rem;\n  }\n\n  .stat-label {\n    font-size: 0.65rem;\n    letter-spacing: 0.02em;\n  }\n\n  .form-grid-2 {\n    grid-template-columns: 1fr;\n    gap: 0.75rem;\n  }\n\n  .admin-cards-grid {\n    grid-template-columns: 1fr;\n    gap: 1rem;\n  }\n\n  /* 2-Column Compact Gallery Grid on Phones */\n  .admin-gallery-grid {\n    grid-template-columns: repeat(2, 1fr);\n    gap: 0.75rem;\n  }\n\n  .admin-gallery-card {\n    height: 210px;\n    border-radius: var(--radius-md);\n  }\n\n  .gallery-card-title {\n    font-size: 0.9rem;\n  }\n\n  .gallery-card-actions {\n    margin-top: 0.4rem;\n  }\n\n  .gallery-card-actions .btn-sm {\n    padding: 0.35rem 0.65rem;\n    font-size: 0.7rem;\n  }\n\n  .admin-reviews-grid {\n    grid-template-columns: 1fr;\n    gap: 1rem;\n  }\n\n  .settings-grid {\n    grid-template-columns: 1fr;\n    gap: 1.25rem;\n  }\n\n  /* Bottom-Sheet Style Modal for Thumbs Reach */\n  .admin-modal {\n    padding: 0;\n    align-items: flex-end;\n  }\n\n  .modal-content {\n    max-height: 88vh;\n    padding: 1.25rem 1rem;\n    border-radius: var(--radius-lg) var(--radius-lg) 0 0;\n    border-bottom: none;\n  }\n\n  .modal-title {\n    font-size: 1.2rem;\n  }\n\n  .modal-footer {\n    flex-direction: column-reverse;\n    gap: 0.6rem;\n  }\n\n  .modal-footer .btn {\n    width: 100%;\n    justify-content: center;\n  }\n\n  .admin-app-footer {\n    margin-top: 2rem;\n    padding-bottom: 2rem;\n    font-size: 0.7rem;\n    gap: 0.5rem;\n  }\n}\n\n/* ==========================================================================\n   WEBVERSE SOFTWARE SOLUTIONS BRANDING & SUPPORT CARDS\n   ========================================================================== */\n.developer-badge {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  padding: 0.85rem;\n  background: rgba(212, 175, 55, 0.06);\n  border: 1px solid rgba(212, 175, 55, 0.2);\n  border-radius: var(--radius-md);\n  transition: var(--transition);\n}\n\n.developer-badge:hover {\n  background: rgba(212, 175, 55, 0.12);\n  border-color: rgba(212, 175, 55, 0.4);\n}\n\n.dev-badge-icon {\n  width: 34px;\n  height: 34px;\n  border-radius: var(--radius-sm);\n  background: rgba(212, 175, 55, 0.15);\n  color: var(--color-gold-primary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.95rem;\n  flex-shrink: 0;\n}\n\n.dev-badge-info {\n  display: flex;\n  flex-direction: column;\n  line-height: 1.25;\n}\n\n.dev-badge-title {\n  font-size: 0.825rem;\n  font-weight: 700;\n  color: #FFFFFF;\n  letter-spacing: 0.02em;\n}\n\n.dev-badge-sub {\n  font-size: 0.68rem;\n  color: var(--color-text-dim);\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n}\n\n/* Developer & Tech Support Card */\n.developer-support-card {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  border-color: rgba(212, 175, 55, 0.25);\n  background: linear-gradient(135deg, rgba(30, 15, 26, 0.75) 0%, rgba(20, 8, 17, 0.85) 100%);\n}\n\n.support-brand {\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n  margin-bottom: 0.85rem;\n}\n\n.support-logo-badge {\n  width: 44px;\n  height: 44px;\n  border-radius: var(--radius-md);\n  background: rgba(212, 175, 55, 0.15);\n  border: 1px solid rgba(212, 175, 55, 0.35);\n  color: var(--color-gold-primary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.15rem;\n  flex-shrink: 0;\n}\n\n.support-company-name {\n  font-family: var(--font-serif);\n  font-size: 1.35rem;\n  font-weight: 700;\n  color: #FFFFFF;\n  line-height: 1.2;\n}\n\n.support-company-tag {\n  font-size: 0.72rem;\n  color: var(--color-rose-gold);\n  letter-spacing: 0.04em;\n  display: block;\n}\n\n.support-card-desc {\n  font-size: 0.825rem;\n  color: var(--color-text-muted);\n  line-height: 1.5;\n  margin-bottom: 1.25rem;\n}\n\n.support-contacts-minimal {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.65rem;\n}\n\n.contact-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.5rem 0.9rem;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(212, 175, 55, 0.25);\n  border-radius: var(--radius-full);\n  color: var(--color-gold-light);\n  font-size: 0.775rem;\n  font-weight: 600;\n  text-decoration: none;\n  transition: var(--transition);\n}\n\n.contact-pill:hover {\n  background: rgba(212, 175, 55, 0.2);\n  border-color: var(--color-gold-primary);\n  color: #FFFFFF;\n  transform: translateY(-2px);\n}\n\n.contact-pill.whatsapp {\n  border-color: rgba(37, 211, 102, 0.35);\n  color: #86EFAC;\n}\n\n.contact-pill.whatsapp:hover {\n  background: rgba(37, 211, 102, 0.2);\n  border-color: #25D366;\n  color: #FFFFFF;\n}\n\n.contact-pill.email {\n  border-color: rgba(197, 155, 118, 0.35);\n  color: var(--color-rose-gold);\n}\n\n.contact-pill.email:hover {\n  background: rgba(197, 155, 118, 0.2);\n  border-color: var(--color-rose-gold);\n  color: #FFFFFF;\n}\n\n/* Admin App Footer */\n.admin-app-footer {\n  margin-top: 3rem;\n  padding-top: 1.25rem;\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-wrap: wrap;\n  gap: 0.75rem;\n  font-size: 0.75rem;\n  color: var(--color-text-dim);\n  text-align: center;\n}\n\n.developer-link {\n  color: var(--color-gold-light);\n  text-decoration: none;\n  font-weight: 600;\n  transition: var(--transition);\n}\n\n.developer-link:hover {\n  color: var(--color-gold-primary);\n  text-decoration: underline;\n}\n\n.footer-divider {\n  color: rgba(255, 255, 255, 0.15);\n}\n\n.footer-support-phone {\n  color: var(--color-text-muted);\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n}\n\n.login-developer-credit {\n  margin-top: 0.4rem;\n  font-size: 0.7rem;\n  color: var(--color-text-dim);\n}\n\n.login-developer-credit strong {\n  color: var(--color-gold-light);\n}\n";
export const ADMIN_JS = "/**\n * RAKHI MAKEOVERS - LUXURY ADMIN DASHBOARD ENGINE\n */\n\nconst API_BASE = '/api';\nlet authToken = localStorage.getItem('rakhi_admin_token') || '';\n\n// App State\nlet servicesData = [];\nlet galleryData = [];\nlet reviewsData = [];\nlet pendingDeleteAction = null;\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  initAuth();\n  initSidebarAndTabs();\n  initFormListeners();\n  initDropzones();\n});\n\n/* ==========================================================================\n   1. AUTHENTICATION & SESSION MANAGEMENT\n   ========================================================================== */\nfunction initAuth() {\n  const loginForm = document.getElementById('admin-login-form');\n  const togglePwBtn = document.getElementById('toggle-password');\n  const logoutBtn = document.getElementById('btn-logout');\n\n  // Password visibility toggle\n  if (togglePwBtn) {\n    togglePwBtn.addEventListener('click', () => {\n      const pwInput = document.getElementById('login-password');\n      if (pwInput.type === 'password') {\n        pwInput.type = 'text';\n        togglePwBtn.innerHTML = '<i class=\"fa-regular fa-eye-slash\"></i>';\n      } else {\n        pwInput.type = 'password';\n        togglePwBtn.innerHTML = '<i class=\"fa-regular fa-eye\"></i>';\n      }\n    });\n  }\n\n  // Handle Login Submit\n  if (loginForm) {\n    loginForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const username = document.getElementById('login-username').value.trim();\n      const password = document.getElementById('login-password').value;\n      const submitBtn = document.getElementById('btn-login-submit');\n      const errorMsg = document.getElementById('login-error-msg');\n\n      errorMsg.style.display = 'none';\n      submitBtn.disabled = true;\n      submitBtn.innerHTML = '<i class=\"fa-solid fa-circle-notch fa-spin\"></i> Signing In...';\n\n      try {\n        const res = await fetch(`${API_BASE}/auth/login`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ username, password })\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success && data.token) {\n          authToken = data.token;\n          localStorage.setItem('rakhi_admin_token', authToken);\n          showToast('Welcome back, Master Admin!', 'success');\n          showAdminDashboard();\n        } else {\n          errorMsg.textContent = data.message || 'Invalid username or password';\n          errorMsg.style.display = 'block';\n        }\n      } catch (err) {\n        errorMsg.textContent = 'Connection error. Please ensure the server is running.';\n        errorMsg.style.display = 'block';\n      } finally {\n        submitBtn.disabled = false;\n        submitBtn.innerHTML = '<i class=\"fa-solid fa-arrow-right-to-bracket\"></i> Sign In to Dashboard';\n      }\n    });\n  }\n\n  // Handle Logout\n  if (logoutBtn) {\n    logoutBtn.addEventListener('click', async () => {\n      try {\n        await fetch(`${API_BASE}/auth/logout`, {\n          method: 'POST',\n          headers: { 'Authorization': `Bearer ${authToken}` }\n        });\n      } catch (e) {}\n\n      localStorage.removeItem('rakhi_admin_token');\n      authToken = '';\n      showToast('You have been logged out safely.', 'success');\n      showLoginScreen();\n    });\n  }\n\n  // Auto-verify existing token\n  if (authToken) {\n    verifySession();\n  } else {\n    showLoginScreen();\n  }\n}\n\nasync function verifySession() {\n  try {\n    const res = await fetch(`${API_BASE}/auth/me`, {\n      headers: { 'Authorization': `Bearer ${authToken}` }\n    });\n    if (res.ok) {\n      showAdminDashboard();\n    } else {\n      localStorage.removeItem('rakhi_admin_token');\n      authToken = '';\n      showLoginScreen();\n    }\n  } catch (err) {\n    // If offline or local dev, gracefully show dashboard if token exists\n    showAdminDashboard();\n  }\n}\n\nfunction showLoginScreen() {\n  document.getElementById('login-screen').style.display = 'flex';\n  document.getElementById('admin-app').style.display = 'none';\n}\n\nfunction showAdminDashboard() {\n  document.getElementById('login-screen').style.display = 'none';\n  document.getElementById('admin-app').style.display = 'flex';\n  loadAllData();\n}\n\n/* ==========================================================================\n   2. NAVIGATION & TABS\n   ========================================================================== */\nfunction initSidebarAndTabs() {\n  const navItems = document.querySelectorAll('.sidebar-nav .nav-item, .mobile-admin-tabs .mobile-tab-btn');\n  const sidebarToggle = document.getElementById('sidebar-toggle');\n  const sidebar = document.getElementById('admin-sidebar');\n\n  navItems.forEach(item => {\n    item.addEventListener('click', () => {\n      const targetTab = item.getAttribute('data-tab');\n      switchTab(targetTab);\n      if (window.innerWidth <= 768 && sidebar) {\n        sidebar.classList.remove('open');\n      }\n    });\n  });\n\n  if (sidebarToggle && sidebar) {\n    sidebarToggle.addEventListener('click', () => {\n      sidebar.classList.toggle('open');\n    });\n  }\n}\n\nfunction switchTab(tabId) {\n  document.querySelectorAll('.sidebar-nav .nav-item, .mobile-admin-tabs .mobile-tab-btn').forEach(btn => {\n    btn.classList.toggle('active', btn.getAttribute('data-tab') === tabId);\n  });\n\n  document.querySelectorAll('.tab-pane').forEach(pane => {\n    pane.classList.toggle('active', pane.id === tabId);\n  });\n}\n\n/* ==========================================================================\n   3. DATA LOADING & DASHBOARD STATS\n   ========================================================================== */\nasync function loadAllData() {\n  await Promise.all([\n    fetchServices(),\n    fetchGallery(),\n    fetchReviews()\n  ]);\n  updateDashboardStats();\n}\n\nfunction updateDashboardStats() {\n  const statServices = document.getElementById('stat-services-count');\n  const statGallery = document.getElementById('stat-gallery-count');\n  const statReviews = document.getElementById('stat-reviews-count');\n\n  if (statServices) statServices.textContent = servicesData.length;\n  if (statGallery) statGallery.textContent = galleryData.length;\n  if (statReviews) statReviews.textContent = reviewsData.length;\n}\n\n/* ==========================================================================\n   4. SERVICES MANAGER\n   ========================================================================== */\nasync function fetchServices() {\n  const container = document.getElementById('services-list-container');\n  try {\n    const res = await fetch(`${API_BASE}/services`);\n    if (res.ok) {\n      servicesData = await res.json();\n      renderServicesList();\n    }\n  } catch (err) {\n    if (container) container.innerHTML = '<div class=\"alert-banner alert-error\">Failed to load services.</div>';\n  }\n}\n\nfunction renderServicesList() {\n  const container = document.getElementById('services-list-container');\n  if (!container) return;\n\n  if (servicesData.length === 0) {\n    container.innerHTML = '<div class=\"alert-banner\" style=\"grid-column: 1/-1; text-align: center;\">No services found. Click \"Add New Service\" to create one.</div>';\n    return;\n  }\n\n  container.innerHTML = servicesData.map(service => `\n    <div class=\"admin-item-card glass-panel\" data-id=\"${service.id}\">\n      <div class=\"item-card-media\">\n        <img src=\"${escapeHtml(service.image || 'assets/images/bridal_traditional.webp')}\" alt=\"${escapeHtml(service.title)}\" loading=\"lazy\">\n        <span class=\"item-badge-pill\">${escapeHtml(service.category || 'Bridal')}</span>\n        <span class=\"item-duration-pill\"><i class=\"fa-regular fa-clock\"></i> ${escapeHtml(service.duration || '2.5 Hours')}</span>\n      </div>\n      <div class=\"item-card-body\">\n        <h3 class=\"item-card-title\">${escapeHtml(service.title)}</h3>\n        <p class=\"item-card-desc\">${escapeHtml(service.description || '')}</p>\n        <ul class=\"item-inclusions-preview\">\n          ${(service.inclusions || []).slice(0, 3).map(inc => `<li><i class=\"fa-solid fa-check text-gold\"></i> ${escapeHtml(inc)}</li>`).join('')}\n        </ul>\n        <div class=\"item-card-actions\">\n          <button class=\"btn btn-outline-gold btn-sm btn-block\" onclick=\"openServiceModal('${service.id}')\">\n            <i class=\"fa-solid fa-pen-to-square\"></i> Edit\n          </button>\n          <button class=\"btn btn-danger-ghost btn-sm\" onclick=\"confirmDelete('service', '${service.id}', '${escapeHtml(service.title)}')\">\n            <i class=\"fa-solid fa-trash\"></i>\n          </button>\n        </div>\n      </div>\n    </div>\n  `).join('');\n}\n\nfunction openServiceModal(serviceId = null) {\n  const modal = document.getElementById('modal-service');\n  const titleElem = document.getElementById('modal-service-title');\n  const idInput = document.getElementById('service-id');\n  const titleInput = document.getElementById('service-title');\n  const catInput = document.getElementById('service-category');\n  const durationInput = document.getElementById('service-duration');\n  const imgUrlInput = document.getElementById('service-image-url');\n  const descInput = document.getElementById('service-desc');\n  const inclusionsInput = document.getElementById('service-inclusions');\n\n  clearServiceImagePreview();\n\n  if (serviceId) {\n    const service = servicesData.find(s => s.id === serviceId);\n    if (!service) return;\n    titleElem.textContent = 'Edit Service';\n    idInput.value = service.id;\n    titleInput.value = service.title || '';\n    catInput.value = service.category || 'bridal';\n    durationInput.value = service.duration || '';\n    imgUrlInput.value = service.image || '';\n    descInput.value = service.description || '';\n    inclusionsInput.value = (service.inclusions || []).join('\\n');\n\n    if (service.image) {\n      showServiceImagePreview(service.image);\n    }\n  } else {\n    titleElem.textContent = 'Add New Service';\n    idInput.value = '';\n    titleInput.value = '';\n    catInput.value = 'bridal';\n    durationInput.value = '2.5 Hours';\n    imgUrlInput.value = 'assets/images/bridal_traditional.webp';\n    descInput.value = '';\n    inclusionsInput.value = 'Sweat-Resistant Radiant Base\\nClassic Defined Winged Kohl\\nRoyal Saree Pleating & Draping';\n  }\n\n  openModal('modal-service');\n}\n\n/* ==========================================================================\n   5. LOOKBOOK GALLERY MANAGER\n   ========================================================================== */\nasync function fetchGallery() {\n  const container = document.getElementById('gallery-list-container');\n  try {\n    const res = await fetch(`${API_BASE}/gallery`);\n    if (res.ok) {\n      galleryData = await res.json();\n      renderGalleryList();\n    }\n  } catch (err) {\n    if (container) container.innerHTML = '<div class=\"alert-banner alert-error\">Failed to load lookbook gallery.</div>';\n  }\n}\n\nfunction renderGalleryList() {\n  const container = document.getElementById('gallery-list-container');\n  if (!container) return;\n\n  if (galleryData.length === 0) {\n    container.innerHTML = '<div class=\"alert-banner\" style=\"grid-column: 1/-1; text-align: center;\">No photos found. Click \"Upload Lookbook Photo\" to add one.</div>';\n    return;\n  }\n\n  container.innerHTML = galleryData.map(item => `\n    <div class=\"admin-gallery-card glass-panel\" data-id=\"${item.id}\">\n      <img src=\"${escapeHtml(item.image)}\" alt=\"${escapeHtml(item.altText || item.title)}\" loading=\"lazy\">\n      <div class=\"gallery-card-overlay\">\n        <span class=\"gallery-card-cat\">${escapeHtml(item.categoryName || item.category)}</span>\n        <h4 class=\"gallery-card-title\">${escapeHtml(item.title)}</h4>\n        <div class=\"gallery-card-actions\">\n          <button class=\"btn btn-outline-gold btn-sm btn-block\" onclick=\"openGalleryModal('${item.id}')\">\n            <i class=\"fa-solid fa-pen\"></i> Edit\n          </button>\n          <button class=\"btn btn-danger-ghost btn-sm\" onclick=\"confirmDelete('gallery', '${item.id}', '${escapeHtml(item.title)}')\">\n            <i class=\"fa-solid fa-trash\"></i>\n          </button>\n        </div>\n      </div>\n    </div>\n  `).join('');\n}\n\nfunction openGalleryModal(galleryId = null) {\n  const modal = document.getElementById('modal-gallery');\n  const titleElem = document.getElementById('modal-gallery-title');\n  const idInput = document.getElementById('gallery-id');\n  const titleInput = document.getElementById('gallery-title');\n  const catInput = document.getElementById('gallery-category');\n  const catNameInput = document.getElementById('gallery-category-name');\n  const imgUrlInput = document.getElementById('gallery-image-url');\n  const descInput = document.getElementById('gallery-desc');\n  const altInput = document.getElementById('gallery-alt');\n\n  clearGalleryImagePreview();\n\n  if (galleryId) {\n    const item = galleryData.find(g => g.id === galleryId);\n    if (!item) return;\n    titleElem.textContent = 'Edit Lookbook Photo';\n    idInput.value = item.id;\n    titleInput.value = item.title || '';\n    catInput.value = item.category || 'traditional';\n    catNameInput.value = item.categoryName || 'Traditional Red';\n    imgUrlInput.value = item.image || '';\n    descInput.value = item.description || '';\n    altInput.value = item.altText || '';\n\n    if (item.image) {\n      showGalleryImagePreview(item.image);\n    }\n  } else {\n    titleElem.textContent = 'Upload Lookbook Photo';\n    idInput.value = '';\n    titleInput.value = '';\n    catInput.value = 'traditional';\n    catNameInput.value = 'Traditional Red';\n    imgUrlInput.value = '';\n    descInput.value = '';\n    altInput.value = '';\n  }\n\n  // Sync category name helper\n  catInput.onchange = () => {\n    const map = {\n      'bridal': 'Bridal Royalty',\n      'glam': 'Glam & Saree',\n      'beauty': 'Classic Beauty',\n      'traditional': 'Traditional Red',\n      'pastel': 'Pastel & Modern',\n      'temple': 'Temple & Nikah',\n      'reception': 'Reception & Sangeet'\n    };\n    catNameInput.value = map[catInput.value] || catInput.value;\n  };\n\n  openModal('modal-gallery');\n}\n\n/* ==========================================================================\n   6. REVIEWS & TESTIMONIALS MANAGER\n   ========================================================================== */\nasync function fetchReviews() {\n  const container = document.getElementById('reviews-list-container');\n  try {\n    const res = await fetch(`${API_BASE}/reviews`);\n    if (res.ok) {\n      reviewsData = await res.json();\n      renderReviewsList();\n    }\n  } catch (err) {\n    if (container) container.innerHTML = '<div class=\"alert-banner alert-error\">Failed to load reviews.</div>';\n  }\n}\n\nfunction renderReviewsList() {\n  const container = document.getElementById('reviews-list-container');\n  if (!container) return;\n\n  if (reviewsData.length === 0) {\n    container.innerHTML = '<div class=\"alert-banner\" style=\"grid-column: 1/-1; text-align: center;\">No reviews found. Click \"Add New Review\" to add one.</div>';\n    return;\n  }\n\n  container.innerHTML = reviewsData.map(rev => `\n    <div class=\"admin-review-card glass-panel\" data-id=\"${rev.id}\">\n      <div>\n        <div class=\"review-card-top\">\n          <img src=\"${escapeHtml(rev.avatarImage || 'assets/images/bridal_pastel.webp')}\" alt=\"${escapeHtml(rev.authorName)}\" class=\"review-avatar-img\">\n          <div>\n            <div class=\"review-author-name\">${escapeHtml(rev.authorName)}</div>\n            <div class=\"review-meta\">${escapeHtml(rev.source || 'Google Review')} &bull; ${escapeHtml(rev.timeAgo || '')}</div>\n          </div>\n        </div>\n        <div class=\"review-stars\">\n          ${'★'.repeat(rev.rating || 5)}${'☆'.repeat(5 - (rev.rating || 5))}\n        </div>\n        <p class=\"review-quote-text\">“${escapeHtml(rev.reviewText)}”</p>\n      </div>\n      <div class=\"item-card-actions\">\n        <button class=\"btn btn-outline-gold btn-sm btn-block\" onclick=\"openReviewModal('${rev.id}')\">\n          <i class=\"fa-solid fa-pen\"></i> Edit\n        </button>\n        <button class=\"btn btn-danger-ghost btn-sm\" onclick=\"confirmDelete('review', '${rev.id}', '${escapeHtml(rev.authorName)}')\">\n          <i class=\"fa-solid fa-trash\"></i>\n        </button>\n      </div>\n    </div>\n  `).join('');\n}\n\nfunction openReviewModal(reviewId = null) {\n  const modal = document.getElementById('modal-review');\n  const titleElem = document.getElementById('modal-review-title');\n  const idInput = document.getElementById('review-id');\n  const authorInput = document.getElementById('review-author');\n  const ratingInput = document.getElementById('review-rating');\n  const sourceInput = document.getElementById('review-source');\n  const timeInput = document.getElementById('review-time');\n  const urlInput = document.getElementById('review-url');\n  const avatarInput = document.getElementById('review-avatar');\n  const textInput = document.getElementById('review-text');\n\n  if (reviewId) {\n    const rev = reviewsData.find(r => r.id === reviewId);\n    if (!rev) return;\n    titleElem.textContent = 'Edit Client Review';\n    idInput.value = rev.id;\n    authorInput.value = rev.authorName || '';\n    ratingInput.value = rev.rating || 5;\n    sourceInput.value = rev.source || 'Google Verified Review';\n    timeInput.value = rev.timeAgo || '';\n    urlInput.value = rev.authorProfileUrl || '';\n    avatarInput.value = rev.avatarImage || 'assets/images/bridal_pastel.webp';\n    textInput.value = rev.reviewText || '';\n  } else {\n    titleElem.textContent = 'Add Client Review';\n    idInput.value = '';\n    authorInput.value = '';\n    ratingInput.value = '5';\n    sourceInput.value = 'Google Verified Review';\n    timeInput.value = 'Recently';\n    urlInput.value = '';\n    avatarInput.value = 'assets/images/bridal_pastel.webp';\n    textInput.value = '';\n  }\n\n  openModal('modal-review');\n}\n\n/* ==========================================================================\n   7. FORM SUBMISSIONS & SAVING\n   ========================================================================== */\nfunction initFormListeners() {\n  // Add/Edit Service Form Submit\n  const serviceForm = document.getElementById('form-service');\n  if (serviceForm) {\n    serviceForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const saveBtn = document.getElementById('btn-save-service');\n      const id = document.getElementById('service-id').value;\n      const title = document.getElementById('service-title').value.trim();\n      const category = document.getElementById('service-category').value;\n      const duration = document.getElementById('service-duration').value.trim();\n      const image = document.getElementById('service-image-url').value.trim() || 'assets/images/bridal_traditional.webp';\n      const description = document.getElementById('service-desc').value.trim();\n      const inclusions = document.getElementById('service-inclusions').value\n        .split('\\n')\n        .map(s => s.trim())\n        .filter(Boolean);\n\n      const payload = { title, category, duration, image, description, inclusions };\n\n      saveBtn.disabled = true;\n      saveBtn.textContent = 'Saving...';\n\n      try {\n        const url = id ? `${API_BASE}/services/${id}` : `${API_BASE}/services`;\n        const method = id ? 'PUT' : 'POST';\n\n        const res = await fetch(url, {\n          method,\n          headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${authToken}`\n          },\n          body: JSON.stringify(payload)\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast(id ? 'Service updated successfully!' : 'New service created!', 'success');\n          closeModal('modal-service');\n          await fetchServices();\n          updateDashboardStats();\n        } else {\n          showToast(data.message || 'Failed to save service', 'error');\n        }\n      } catch (err) {\n        showToast('Error connecting to server', 'error');\n      } finally {\n        saveBtn.disabled = false;\n        saveBtn.textContent = 'Save Service';\n      }\n    });\n  }\n\n  // Add/Edit Gallery Form Submit\n  const galleryForm = document.getElementById('form-gallery');\n  if (galleryForm) {\n    galleryForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const saveBtn = document.getElementById('btn-save-gallery');\n      const id = document.getElementById('gallery-id').value;\n      const title = document.getElementById('gallery-title').value.trim();\n      const category = document.getElementById('gallery-category').value;\n      const categoryName = document.getElementById('gallery-category-name').value.trim();\n      const image = document.getElementById('gallery-image-url').value.trim();\n      const description = document.getElementById('gallery-desc').value.trim();\n      const altText = document.getElementById('gallery-alt').value.trim() || title;\n\n      if (!image) {\n        showToast('Please upload or enter an image URL', 'error');\n        return;\n      }\n\n      const payload = { title, category, categoryName, image, description, altText };\n\n      saveBtn.disabled = true;\n      saveBtn.textContent = 'Saving...';\n\n      try {\n        const url = id ? `${API_BASE}/gallery/${id}` : `${API_BASE}/gallery`;\n        const method = id ? 'PUT' : 'POST';\n\n        const res = await fetch(url, {\n          method,\n          headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${authToken}`\n          },\n          body: JSON.stringify(payload)\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast(id ? 'Lookbook photo updated!' : 'New photo added to Lookbook!', 'success');\n          closeModal('modal-gallery');\n          await fetchGallery();\n          updateDashboardStats();\n        } else {\n          showToast(data.message || 'Failed to save photo', 'error');\n        }\n      } catch (err) {\n        showToast('Error connecting to server', 'error');\n      } finally {\n        saveBtn.disabled = false;\n        saveBtn.textContent = 'Save Photo';\n      }\n    });\n  }\n\n  // Add/Edit Review Form Submit\n  const reviewForm = document.getElementById('form-review');\n  if (reviewForm) {\n    reviewForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const saveBtn = document.getElementById('btn-save-review');\n      const id = document.getElementById('review-id').value;\n      const authorName = document.getElementById('review-author').value.trim();\n      const rating = parseInt(document.getElementById('review-rating').value, 10) || 5;\n      const source = document.getElementById('review-source').value.trim();\n      const timeAgo = document.getElementById('review-time').value.trim();\n      const authorProfileUrl = document.getElementById('review-url').value.trim();\n      const avatarImage = document.getElementById('review-avatar').value.trim() || 'assets/images/bridal_pastel.webp';\n      const reviewText = document.getElementById('review-text').value.trim();\n\n      const payload = { authorName, rating, source, timeAgo, authorProfileUrl, avatarImage, reviewText };\n\n      saveBtn.disabled = true;\n      saveBtn.textContent = 'Saving...';\n\n      try {\n        const url = id ? `${API_BASE}/reviews/${id}` : `${API_BASE}/reviews`;\n        const method = id ? 'PUT' : 'POST';\n\n        const res = await fetch(url, {\n          method,\n          headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${authToken}`\n          },\n          body: JSON.stringify(payload)\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast(id ? 'Review updated!' : 'Client review added!', 'success');\n          closeModal('modal-review');\n          await fetchReviews();\n          updateDashboardStats();\n        } else {\n          showToast(data.message || 'Failed to save review', 'error');\n        }\n      } catch (err) {\n        showToast('Error connecting to server', 'error');\n      } finally {\n        saveBtn.disabled = false;\n        saveBtn.textContent = 'Save Review';\n      }\n    });\n  }\n\n  // Change Password Form Submit\n  const pwForm = document.getElementById('change-password-form');\n  if (pwForm) {\n    pwForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const currentPassword = document.getElementById('current-password').value;\n      const newPassword = document.getElementById('new-password').value;\n      const confirmPassword = document.getElementById('confirm-password').value;\n      const statusMsg = document.getElementById('pw-status-msg');\n      const saveBtn = document.getElementById('btn-save-password');\n\n      statusMsg.style.display = 'none';\n\n      if (newPassword.length < 8) {\n        statusMsg.className = 'alert-banner alert-error';\n        statusMsg.textContent = 'New password must be at least 8 characters long.';\n        statusMsg.style.display = 'block';\n        return;\n      }\n\n      if (newPassword !== confirmPassword) {\n        statusMsg.className = 'alert-banner alert-error';\n        statusMsg.textContent = 'New passwords do not match.';\n        statusMsg.style.display = 'block';\n        return;\n      }\n\n      saveBtn.disabled = true;\n      saveBtn.innerHTML = '<i class=\"fa-solid fa-circle-notch fa-spin\"></i> Updating...';\n\n      try {\n        const res = await fetch(`${API_BASE}/auth/change-password`, {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${authToken}`\n          },\n          body: JSON.stringify({ currentPassword, newPassword })\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success) {\n          statusMsg.className = 'alert-banner alert-success';\n          statusMsg.textContent = 'Admin password updated successfully!';\n          statusMsg.style.display = 'block';\n          pwForm.reset();\n          showToast('Master password updated!', 'success');\n        } else {\n          statusMsg.className = 'alert-banner alert-error';\n          statusMsg.textContent = data.message || 'Failed to update password.';\n          statusMsg.style.display = 'block';\n        }\n      } catch (err) {\n        statusMsg.className = 'alert-banner alert-error';\n        statusMsg.textContent = 'Error connecting to server.';\n        statusMsg.style.display = 'block';\n      } finally {\n        saveBtn.disabled = false;\n        saveBtn.innerHTML = '<i class=\"fa-solid fa-shield-check\"></i> Update Password';\n      }\n    });\n  }\n\n  // Delete Confirmation Handler\n  const confirmDeleteBtn = document.getElementById('btn-confirm-delete');\n  if (confirmDeleteBtn) {\n    confirmDeleteBtn.addEventListener('click', async () => {\n      if (!pendingDeleteAction) return;\n\n      const { type, id } = pendingDeleteAction;\n      confirmDeleteBtn.disabled = true;\n      confirmDeleteBtn.textContent = 'Deleting...';\n\n      try {\n        let endpoint = '';\n        if (type === 'service') endpoint = `${API_BASE}/services/${id}`;\n        if (type === 'gallery') endpoint = `${API_BASE}/gallery/${id}`;\n        if (type === 'review') endpoint = `${API_BASE}/reviews/${id}`;\n\n        const res = await fetch(endpoint, {\n          method: 'DELETE',\n          headers: { 'Authorization': `Bearer ${authToken}` }\n        });\n\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast('Item deleted successfully.', 'success');\n          closeModal('modal-delete');\n          if (type === 'service') await fetchServices();\n          if (type === 'gallery') await fetchGallery();\n          if (type === 'review') await fetchReviews();\n          updateDashboardStats();\n        } else {\n          showToast(data.message || 'Delete failed', 'error');\n        }\n      } catch (err) {\n        showToast('Error deleting item', 'error');\n      } finally {\n        confirmDeleteBtn.disabled = false;\n        confirmDeleteBtn.textContent = 'Yes, Delete';\n        pendingDeleteAction = null;\n      }\n    });\n  }\n}\n\nfunction confirmDelete(type, id, name) {\n  pendingDeleteAction = { type, id };\n  const msgElem = document.getElementById('delete-confirm-message');\n  if (msgElem) {\n    msgElem.innerHTML = `Are you sure you want to permanently delete <strong>\"${escapeHtml(name)}\"</strong>?`;\n  }\n  openModal('modal-delete');\n}\n\n/* ==========================================================================\n   8. IMAGE DROPZONE & UPLOAD HANDLERS\n   ========================================================================== */\nfunction initDropzones() {\n  setupImageDropzone('service-dropzone', 'service-file-input', (url) => {\n    document.getElementById('service-image-url').value = url;\n    showServiceImagePreview(url);\n  });\n\n  setupImageDropzone('gallery-dropzone', 'gallery-file-input', (url) => {\n    document.getElementById('gallery-image-url').value = url;\n    showGalleryImagePreview(url);\n  });\n}\n\nfunction setupImageDropzone(dropzoneId, inputId, onUploaded) {\n  const dropzone = document.getElementById(dropzoneId);\n  const input = document.getElementById(inputId);\n  if (!dropzone || !input) return;\n\n  ['dragenter', 'dragover'].forEach(eventName => {\n    dropzone.addEventListener(eventName, (e) => {\n      e.preventDefault();\n      dropzone.style.borderColor = 'var(--color-gold-primary)';\n      dropzone.style.background = 'rgba(212, 175, 55, 0.1)';\n    });\n  });\n\n  ['dragleave', 'drop'].forEach(eventName => {\n    dropzone.addEventListener(eventName, (e) => {\n      e.preventDefault();\n      dropzone.style.borderColor = '';\n      dropzone.style.background = '';\n    });\n  });\n\n  dropzone.addEventListener('drop', (e) => {\n    const files = e.dataTransfer.files;\n    if (files && files.length > 0) {\n      handleFileUpload(files[0], onUploaded);\n    }\n  });\n\n  input.addEventListener('change', () => {\n    if (input.files && input.files.length > 0) {\n      handleFileUpload(input.files[0], onUploaded);\n    }\n  });\n}\n\nasync function handleFileUpload(file, onUploaded) {\n  if (!file.type.startsWith('image/')) {\n    showToast('Please select a valid image file (WebP, JPG, PNG).', 'error');\n    return;\n  }\n\n  showToast('Uploading image...', 'success');\n\n  // Convert to Base64 data URL\n  const reader = new FileReader();\n  reader.onload = async () => {\n    const base64Data = reader.result;\n\n    try {\n      const res = await fetch(`${API_BASE}/upload`, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n          'Authorization': `Bearer ${authToken}`\n        },\n        body: JSON.stringify({ data: base64Data, filename: file.name })\n      });\n\n      const data = await res.json();\n      if (res.ok && data.success && data.url) {\n        showToast('Image uploaded successfully!', 'success');\n        onUploaded(data.url);\n      } else {\n        // Fallback to direct base64 data URI if server is in client-only mode\n        onUploaded(base64Data);\n        showToast('Image processed for preview!', 'success');\n      }\n    } catch (err) {\n      onUploaded(base64Data);\n      showToast('Image saved as preview data.', 'success');\n    }\n  };\n  reader.readAsDataURL(file);\n}\n\nfunction showServiceImagePreview(src) {\n  const previewBox = document.getElementById('service-img-preview');\n  const dropContent = document.querySelector('#service-dropzone .dropzone-content');\n  if (previewBox && dropContent) {\n    previewBox.querySelector('img').src = src;\n    previewBox.style.display = 'block';\n    dropContent.style.display = 'none';\n  }\n}\n\nfunction clearServiceImagePreview() {\n  const previewBox = document.getElementById('service-img-preview');\n  const dropContent = document.querySelector('#service-dropzone .dropzone-content');\n  const imgInput = document.getElementById('service-image-url');\n  if (previewBox && dropContent) {\n    previewBox.style.display = 'none';\n    dropContent.style.display = 'block';\n  }\n  if (imgInput) imgInput.value = '';\n}\n\nfunction showGalleryImagePreview(src) {\n  const previewBox = document.getElementById('gallery-img-preview');\n  const dropContent = document.querySelector('#gallery-dropzone .dropzone-content');\n  if (previewBox && dropContent) {\n    previewBox.querySelector('img').src = src;\n    previewBox.style.display = 'block';\n    dropContent.style.display = 'none';\n  }\n}\n\nfunction clearGalleryImagePreview() {\n  const previewBox = document.getElementById('gallery-img-preview');\n  const dropContent = document.querySelector('#gallery-dropzone .dropzone-content');\n  const imgInput = document.getElementById('gallery-image-url');\n  if (previewBox && dropContent) {\n    previewBox.style.display = 'none';\n    dropContent.style.display = 'block';\n  }\n  if (imgInput) imgInput.value = '';\n}\n\n/* ==========================================================================\n   9. MODAL & TOAST HELPERS\n   ========================================================================== */\nfunction openModal(modalId) {\n  const modal = document.getElementById(modalId);\n  if (modal) {\n    modal.classList.add('active');\n    document.body.style.overflow = 'hidden';\n  }\n}\n\nfunction closeModal(modalId) {\n  const modal = document.getElementById(modalId);\n  if (modal) {\n    modal.classList.remove('active');\n    document.body.style.overflow = 'auto';\n  }\n}\n\n// Close modal on escape or backdrop click\ndocument.addEventListener('keydown', (e) => {\n  if (e.key === 'Escape') {\n    document.querySelectorAll('.admin-modal.active').forEach(m => m.classList.remove('active'));\n    document.body.style.overflow = 'auto';\n  }\n});\n\ndocument.addEventListener('click', (e) => {\n  if (e.target.classList.contains('modal-backdrop')) {\n    e.target.closest('.admin-modal').classList.remove('active');\n    document.body.style.overflow = 'auto';\n  }\n});\n\nfunction showToast(message, type = 'success') {\n  const container = document.getElementById('toast-container');\n  if (!container) return;\n\n  const toast = document.createElement('div');\n  toast.className = `toast toast-${type}`;\n  const icon = type === 'success' ? 'fa-solid fa-circle-check' : 'fa-solid fa-circle-exclamation';\n  toast.innerHTML = `<i class=\"${icon}\"></i> <span>${escapeHtml(message)}</span>`;\n\n  container.appendChild(toast);\n\n  setTimeout(() => {\n    toast.style.opacity = '0';\n    toast.style.transform = 'translateX(40px)';\n    setTimeout(() => toast.remove(), 300);\n  }, 4000);\n}\n\nfunction escapeHtml(str) {\n  if (!str) return '';\n  return String(str)\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&#039;');\n}\n";
